inline float Extended::Tan(float value){return std::tan(value);}
inline float Extended::Asin(float value){return std::asin(value);}
inline float Extended::Acos(float value){return std::acos(value);}
inline float Extended::Atan(float value){return std::atan(value);}
inline float Extended::Exp(float value){return std::exp(value);}
inline float Extended::Log(float value){return std::log(value);}
inline float Extended::Log2(float value){return std::log2(value);}
inline float Extended::Log10(float value){return std::log10(value);}
inline float Extended::Truncate(float value){return std::trunc(value);}
inline float Extended::Fraction(float value){return value-std::floor(value);}
inline float Extended::Sign(float value){return float((value>0)-(value<0));}
inline float Extended::Square(float value){return value*value;}
inline float Extended::Cube(float value){return value*value*value;}
inline float Extended::OneMinus(float value){return 1-value;}
inline float Extended::Saturate(float value){return std::clamp(value,0.0f,1.0f);}
inline float Extended::Sinh(float value){return std::sinh(value);}
inline float Extended::Cosh(float value){return std::cosh(value);}
inline float Extended::Tanh(float value){return std::tanh(value);}
inline float Extended::Atan2(float y,float x){return std::atan2(y,x);}
inline float Extended::Modulo(float a,float b){if(b==0)throw std::invalid_argument("zero divisor");return std::fmod(a,b);}
inline float Extended::Wrap(float value,float min,float max){if(max<=min)throw std::invalid_argument("range");return min+std::fmod(std::fmod(value-min,max-min)+max-min,max-min);}
inline float Extended::InverseLerp(float a,float b,float value){if(a==b)throw std::invalid_argument("range");return (value-a)/(b-a);}
inline float Extended::MapRangeClamped(float value,float inMin,float inMax,float outMin,float outMax){return Math::Lerp(outMin,outMax,std::clamp(Math::MapRange(value,inMin,inMax,0,1),0.0f,1.0f));}
inline float Extended::EaseIn(float alpha,float exponent){return std::pow(std::clamp(alpha,0.0f,1.0f),exponent);}
inline float Extended::EaseOut(float alpha,float exponent){return 1-std::pow(1-std::clamp(alpha,0.0f,1.0f),exponent);}
inline float Extended::EaseInOut(float alpha,float exponent){float t=std::clamp(alpha,0.0f,1.0f);return t<.5f?std::pow(2*t,exponent)*.5f:1-std::pow(2*(1-t),exponent)*.5f;}
inline float Extended::FloatMoveTowards(float current,float target,float distance){float d=std::max(0.0f,distance);return current+std::clamp(target-current,-d,d);}
inline float Extended::SnapFloat(float value,float grid){if(grid<=0)throw std::invalid_argument("grid");return std::round(value/grid)*grid;}
inline bool Extended::GreaterEqual(float a,float b){return a>=b;}
inline bool Extended::LessEqual(float a,float b){return a<=b;}
