inline Vec2 Extended::Vector2Multiply(const Vec2& a,const Vec2& b){return {a.x*b.x,a.y*b.y};}
inline Vec2 Extended::Vector2Divide(const Vec2& a,const Vec2& b){if(b.x==0||b.y==0)throw std::invalid_argument("zero component");return {a.x/b.x,a.y/b.y};}
inline Vec2 Extended::Vector2Min(const Vec2& a,const Vec2& b){return {std::min(a.x,b.x),std::min(a.y,b.y)};}
inline Vec2 Extended::Vector2Max(const Vec2& a,const Vec2& b){return {std::max(a.x,b.x),std::max(a.y,b.y)};}
inline Vec2 Extended::Vector2Abs(const Vec2& value){return {std::abs(value.x),std::abs(value.y)};}
inline Vec2 Extended::Vector2Negate(const Vec2& value){return {-value.x,-value.y};}
inline Vec2 Extended::Vector2Floor(const Vec2& value){return {std::floor(value.x),std::floor(value.y)};}
inline Vec2 Extended::Vector2Ceil(const Vec2& value){return {std::ceil(value.x),std::ceil(value.y)};}
inline bool Extended::Vector2NearlyEqual(const Vec2& a,const Vec2& b,float tolerance){return std::abs(a.x-b.x)<=std::max(0.0f,tolerance)&&std::abs(a.y-b.y)<=std::max(0.0f,tolerance);}
inline bool Extended::Vector2IsZero(const Vec2& value,float tolerance){return std::abs(value.x)<=std::max(0.0f,tolerance)&&std::abs(value.y)<=std::max(0.0f,tolerance);}
inline Vec2 Extended::Vector2Clamp(const Vec2& value,float min,float max){if(min>max)throw std::invalid_argument("range");return {std::clamp(value.x,min,max),std::clamp(value.y,min,max)};}
inline float Extended::Vector2GetX(const Vec2& value){return value.x;}
inline float Extended::Vector2GetY(const Vec2& value){return value.y;}
inline Vec3 Extended::Vector3Multiply(const Vec3& a,const Vec3& b){return {a.x*b.x,a.y*b.y,a.z*b.z};}
inline Vec3 Extended::Vector3Divide(const Vec3& a,const Vec3& b){if(b.x==0||b.y==0||b.z==0)throw std::invalid_argument("zero component");return {a.x/b.x,a.y/b.y,a.z/b.z};}
inline Vec3 Extended::Vector3Min(const Vec3& a,const Vec3& b){return {std::min(a.x,b.x),std::min(a.y,b.y),std::min(a.z,b.z)};}
inline Vec3 Extended::Vector3Max(const Vec3& a,const Vec3& b){return {std::max(a.x,b.x),std::max(a.y,b.y),std::max(a.z,b.z)};}
inline Vec3 Extended::Vector3Abs(const Vec3& value){return {std::abs(value.x),std::abs(value.y),std::abs(value.z)};}
inline Vec3 Extended::Vector3Negate(const Vec3& value){return {-value.x,-value.y,-value.z};}
inline Vec3 Extended::Vector3Floor(const Vec3& value){return {std::floor(value.x),std::floor(value.y),std::floor(value.z)};}
inline Vec3 Extended::Vector3Ceil(const Vec3& value){return {std::ceil(value.x),std::ceil(value.y),std::ceil(value.z)};}
inline bool Extended::Vector3NearlyEqual(const Vec3& a,const Vec3& b,float tolerance){return std::abs(a.x-b.x)<=std::max(0.0f,tolerance)&&std::abs(a.y-b.y)<=std::max(0.0f,tolerance)&&std::abs(a.z-b.z)<=std::max(0.0f,tolerance);}
inline bool Extended::Vector3IsZero(const Vec3& value,float tolerance){return std::abs(value.x)<=std::max(0.0f,tolerance)&&std::abs(value.y)<=std::max(0.0f,tolerance)&&std::abs(value.z)<=std::max(0.0f,tolerance);}
inline Vec3 Extended::Vector3Clamp(const Vec3& value,float min,float max){if(min>max)throw std::invalid_argument("range");return {std::clamp(value.x,min,max),std::clamp(value.y,min,max),std::clamp(value.z,min,max)};}
inline float Extended::Vector3GetX(const Vec3& value){return value.x;}
inline float Extended::Vector3GetY(const Vec3& value){return value.y;}
inline float Extended::Vector3GetZ(const Vec3& value){return value.z;}
inline Vec2 Extended::Vector2Add(const Vec2& a,const Vec2& b){return {a.x+b.x,a.y+b.y};}
inline Vec2 Extended::Vector2Subtract(const Vec2& a,const Vec2& b){return {a.x-b.x,a.y-b.y};}
inline float Extended::Vector2Dot(const Vec2& a,const Vec2& b){return a.x*b.x+a.y*b.y;}
inline float Extended::Vector2Cross(const Vec2& a,const Vec2& b){return a.x*b.y-a.y*b.x;}
inline float Extended::Vector2Distance(const Vec2& a,const Vec2& b){return std::hypot(a.x-b.x,a.y-b.y);}
inline Vec2 Extended::Vector2Lerp(const Vec2& a,const Vec2& b,float alpha){return {Math::Lerp(a.x,b.x,alpha),Math::Lerp(a.y,b.y,alpha)};}
inline Vec2 Extended::Vector2Rotate(const Vec2& value,float degrees){float r=Math::DegreesToRadians(degrees);return {value.x*std::cos(r)-value.y*std::sin(r),value.x*std::sin(r)+value.y*std::cos(r)};}
inline Vec3 Extended::RotateVector(const Vec3& value,const Vec3& rotation){return hb_detail::rotate(value,rotation,false);}
inline Vec3 Extended::UnrotateVector(const Vec3& value,const Vec3& rotation){return hb_detail::rotate(value,rotation,true);}
inline Vec3 Extended::ForwardVector(const Vec3& rotation){return hb_detail::rotate({0,0,1},rotation,false);}
inline Vec3 Extended::RightVector(const Vec3& rotation){return hb_detail::rotate({1,0,0},rotation,false);}
inline Vec3 Extended::UpVector(const Vec3& rotation){return hb_detail::rotate({0,1,0},rotation,false);}
inline float Extended::NormalizeAngle(float degrees){return hb_detail::angle(degrees);}
inline float Extended::DeltaAngle(float a,float b){return hb_detail::angle(b-a);}
inline float Extended::LerpAngle(float a,float b,float alpha){return a+hb_detail::angle(b-a)*alpha;}
inline Vec3 Extended::LookAtRotation(const Vec3& start,const Vec3& target){Vec3 d=target-start;return {Math::RadiansToDegrees(-std::atan2(d.y,std::hypot(d.x,d.z))),Math::RadiansToDegrees(std::atan2(d.x,d.z)),0};}
inline Vec3 Extended::TransformPosition(const Transform& transform,const Vec3& value){return transform.position+hb_detail::rotate({value.x*transform.scale.x,value.y*transform.scale.y,value.z*transform.scale.z},transform.rotation,false);}
inline Vec3 Extended::InverseTransformPosition(const Transform& transform,const Vec3& value){if(transform.scale.x==0||transform.scale.y==0||transform.scale.z==0)throw std::invalid_argument("zero scale");Vec3 v=hb_detail::rotate(value-transform.position,transform.rotation,true);return {v.x/transform.scale.x,v.y/transform.scale.y,v.z/transform.scale.z};}
inline Vec3 Extended::TransformDirection(const Transform& transform,const Vec3& value){return hb_detail::rotate(value,transform.rotation,false);}
inline Vec3 Extended::InverseTransformDirection(const Transform& transform,const Vec3& value){return hb_detail::rotate(value,transform.rotation,true);}
inline float Extended::ColorRed(const Color& value){return value.r;}
inline float Extended::ColorGreen(const Color& value){return value.g;}
inline float Extended::ColorBlue(const Color& value){return value.b;}
inline float Extended::ColorAlpha(const Color& value){return value.a;}
inline Color Extended::ColorLerp(const Color& a,const Color& b,float alpha){float t=std::clamp(alpha,0.0f,1.0f);return {Math::Lerp(a.r,b.r,t),Math::Lerp(a.g,b.g,t),Math::Lerp(a.b,b.b,t),Math::Lerp(a.a,b.a,t)};}
inline Color Extended::ColorMultiply(const Color& a,const Color& b){return {a.r*b.r,a.g*b.g,a.b*b.b,a.a*b.a};}
inline float Extended::ColorLuminance(const Color& value){return value.r*.2126f+value.g*.7152f+value.b*.0722f;}
inline Color Extended::ColorInvert(const Color& value){return {1-value.r,1-value.g,1-value.b,value.a};}
inline Color Extended::SRGBToLinear(const Color& value){return {hb_detail::gamma(value.r,true),hb_detail::gamma(value.g,true),hb_detail::gamma(value.b,true),value.a};}
inline Color Extended::LinearToSRGB(const Color& value){return {hb_detail::gamma(value.r,false),hb_detail::gamma(value.g,false),hb_detail::gamma(value.b,false),value.a};}
inline bool Extended::StringEqual(const std::string& a,const std::string& b){return a==b;}
inline bool Extended::StringNotEqual(const std::string& a,const std::string& b){return a!=b;}
inline bool Extended::StartsWith(const std::string& value,const std::string& search){return value.rfind(search,0)==0;}
inline bool Extended::EndsWith(const std::string& value,const std::string& search){return value.size()>=search.size()&&value.compare(value.size()-search.size(),search.size(),search)==0;}
inline bool Extended::StringIsEmpty(const std::string& value){return value.empty();}
inline int Extended::UnicodeLength(const std::string& value){return int(hb_detail::characters(value).size());}
inline std::string Extended::ReverseString(const std::string& value){auto c=hb_detail::characters(value);std::reverse(c.begin(),c.end());return hb_detail::join(c);}
inline std::string Extended::LeftString(const std::string& value,int count){return hb_detail::slice(value,0,count);}
inline std::string Extended::RightString(const std::string& value,int count){return hb_detail::slice(value,std::max(0,int(hb_detail::characters(value).size())-count),count);}
inline std::string Extended::LeftChop(const std::string& value,int count){return hb_detail::slice(value,0,std::max(0,int(hb_detail::characters(value).size())-std::max(0,count)));}
inline std::string Extended::RightChop(const std::string& value,int count){return hb_detail::slice(value,std::max(0,count),4096);}
inline std::string Extended::Substring(const std::string& value,int start,int count){return hb_detail::slice(value,start,count);}
inline int Extended::FindString(const std::string& value,const std::string& search){auto p=value.find(search);return p==std::string::npos?-1:int(hb_detail::characters(value.substr(0,p)).size());}
inline std::string Extended::ReplaceString(const std::string& value,const std::string& search,const std::string& replacement){return hb_detail::replace(value,search,replacement);}
inline std::vector<std::string> Extended::SplitString(const std::string& value,const std::string& separator){return hb_detail::split(value,separator);}
inline std::string Extended::JoinStrings(const std::vector<std::string>& values,const std::string& separator){return hb_detail::join(values,separator);}
inline std::string Extended::TrimString(const std::string& value){return hb_detail::trim(value);}
inline std::string Extended::LowerString(const std::string& value){std::string r=value;for(char& c:r)if(c>='A'&&c<='Z')c+=32;return r;}
inline std::string Extended::UpperString(const std::string& value){std::string r=value;for(char& c:r)if(c>='a'&&c<='z')c+=-32;return r;}
inline std::string Extended::IntToString(int value){return std::to_string(value);}
inline std::string Extended::BoolToString(bool value){return value?"true":"false";}
inline float Extended::IntToFloat(int value){return float(value);}
inline int Extended::FloatToInt(float value){return hb_detail::toInteger(value);}
inline int Extended::BoolToInt(bool value){return value?1:0;}
inline bool Extended::IntToBool(int value){return value!=0;}
inline Vec3 Extended::Vector2ToVector3(const Vec2& value,float z){return {value.x,value.y,z};}
inline Vec2 Extended::Vector3ToVector2(const Vec3& value){return {value.x,value.y};}
inline int Extended::ArrayBoolLength(const std::vector<bool>& array){return int(array.size());}
inline int Extended::ArrayBoolLastIndex(const std::vector<bool>& array){return int(array.size())-1;}
inline bool Extended::ArrayBoolIsEmpty(const std::vector<bool>& array){return array.empty();}
inline bool Extended::ArrayBoolIsValidIndex(const std::vector<bool>& array,int index){return index>=0&&index<int(array.size());}
inline bool Extended::ArrayBoolGet(const std::vector<bool>& array,int index){if(index<0||index>=int(array.size()))throw std::out_of_range("array index");return array[index];}
inline int Extended::ArrayBoolFind(const std::vector<bool>& array,bool item){for(int i=0;i<int(array.size());i++)if(hb_detail::equal(bool(array[i]),item))return i;return -1;}
inline bool Extended::ArrayBoolContains(const std::vector<bool>& array,bool item){for(auto v:array)if(hb_detail::equal(bool(v),item))return true;return false;}
inline std::vector<bool> Extended::ArrayBoolReverse(const std::vector<bool>& array){auto r=array;std::reverse(r.begin(),r.end());return r;}
inline std::vector<bool> Extended::ArrayBoolAppend(const std::vector<bool>& array,const std::vector<bool>& other){auto r=array;r.insert(r.end(),other.begin(),other.end());if(r.size()>128)throw std::length_error("array limit");return r;}
inline std::vector<bool> Extended::ArrayBoolSlice(const std::vector<bool>& array,int start,int count){int s=std::clamp(start,0,int(array.size())),e=s+std::min(std::max(0,count),int(array.size())-s);return std::vector<bool>(array.begin()+s,array.begin()+e);}
inline std::vector<bool> Extended::ArrayBoolUnique(const std::vector<bool>& array){std::vector<bool> r;for(auto v:array){bool found=false;for(auto p:r)if(hb_detail::equal(bool(v),bool(p)))found=true;if(!found)r.push_back(v);}return r;}
