inline int Extended::ArrayColorFind(const std::vector<Color>& array,const Color& item){for(int i=0;i<int(array.size());i++)if(hb_detail::equal(Color(array[i]),item))return i;return -1;}
inline bool Extended::ArrayColorContains(const std::vector<Color>& array,const Color& item){for(auto v:array)if(hb_detail::equal(Color(v),item))return true;return false;}
inline std::vector<Color> Extended::ArrayColorReverse(const std::vector<Color>& array){auto r=array;std::reverse(r.begin(),r.end());return r;}
inline std::vector<Color> Extended::ArrayColorAppend(const std::vector<Color>& array,const std::vector<Color>& other){auto r=array;r.insert(r.end(),other.begin(),other.end());if(r.size()>128)throw std::length_error("array limit");return r;}
inline std::vector<Color> Extended::ArrayColorSlice(const std::vector<Color>& array,int start,int count){int s=std::clamp(start,0,int(array.size())),e=s+std::min(std::max(0,count),int(array.size())-s);return std::vector<Color>(array.begin()+s,array.begin()+e);}
inline std::vector<Color> Extended::ArrayColorUnique(const std::vector<Color>& array){std::vector<Color> r;for(auto v:array){bool found=false;for(auto p:r)if(hb_detail::equal(Color(v),Color(p)))found=true;if(!found)r.push_back(v);}return r;}
inline int Extended::ArrayTransformLength(const std::vector<Transform>& array){return int(array.size());}
inline int Extended::ArrayTransformLastIndex(const std::vector<Transform>& array){return int(array.size())-1;}
inline bool Extended::ArrayTransformIsEmpty(const std::vector<Transform>& array){return array.empty();}
inline bool Extended::ArrayTransformIsValidIndex(const std::vector<Transform>& array,int index){return index>=0&&index<int(array.size());}
