inline std::vector<Transform> Extended::ArrayTransformSlice(const std::vector<Transform>& array,int start,int count){int s=std::clamp(start,0,int(array.size())),e=s+std::min(std::max(0,count),int(array.size())-s);return std::vector<Transform>(array.begin()+s,array.begin()+e);}
